import React, { useState, useEffect } from 'react';
import './CartPage.css';  // Assuming your CSS is stored in CartPage.css
import { useLocation } from 'react-router-dom';

const CartPage = () => {
  const location = useLocation();  // Get the location object
  const { myuser } = location.state || {};  // Assuming you pass user info in the state
  const [cartItems, setCartItems] = useState([]);  // State to store cart items

  // Fetch cart items when component mounts
  useEffect(() => {
    const userId = myuser ? myuser._id : 'userId';  // Replace with actual user ID from state/context

    // Fetch cart items from backend
    fetch(`http://localhost:5000/api/user/cart?userId=${userId}`)
      .then((response) => response.json())
      .then((data) => {
        if (data.cartItems) {
          setCartItems(data.cartItems);  // Set cart items to state
        } else {
          console.log('No cart items found.');
        }
      })
      .catch((error) => {
        console.error('Error fetching cart items:', error);
      });
  }, [myuser]);  // Depend on user to fetch cart items when user changes

  // Function to increase quantity
  const incrementQuantity = (id) => {
    setCartItems(cartItems.map(item =>
      item.item._id === id ? { ...item, quantity: item.quantity + 1 } : item
    ));
  };

  // Function to decrease quantity with confirmation prompt
  const decrementQuantity = (id) => {
    setCartItems(cartItems.map(item => {
      if (item.item._id === id) {
        if (item.quantity === 1) {
          const confirmDelete = window.confirm(`Are you sure you want to remove ${item.item.name} from the cart?`);
          if (confirmDelete) {
            return null; // Mark for deletion
          } else {
            return item; // Keep the item unchanged
          }
        }
        return { ...item, quantity: item.quantity - 1 };
      }
      return item;
    }).filter(item => item !== null));  // Remove items marked for deletion
  };

  // Calculate subtotal
  const subtotal = cartItems.reduce((total, item) => total + item.item.price * item.quantity, 0);

  return (
    <div className="cart-container">
      <div className="cart-items">
        <h2>MY CART</h2>
        {cartItems.length === 0 ? (
          <p>Your cart is empty.</p> // Message when cart is empty
        ) : (
          cartItems.map(item => (
            <div key={item.item._id} className="cart-item">
              <img src={item.item.imageUrl || '/path/to/default-image.jpg'} alt={item.item.name} className="item-image" />
              <div className="cart-item-details">
                <h4>{item.item.name}</h4>
                <div className="quantity-control">
                  <button className="quantity-button" onClick={() => decrementQuantity(item.item._id)}>-</button>
                  <span className="quantity">{item.quantity}</span>
                  <button className="quantity-button" onClick={() => incrementQuantity(item.item._id)}>+</button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Cart Subtotal */}
      {cartItems.length > 0 && (
        <div className="cart-subtotal">
          <h2>CART SUBTOTAL</h2>
          {cartItems.map(item => (
            <div key={item.item._id} className="subtotal-item">
              <img src={item.item.imageUrl || '/path/to/default-image.jpg'} alt={item.item.name} className="subtotal-image" />
              <div className="subtotal-details">
                <p>{item.item.name}</p>
                <p name="item-quantity-display">X{item.quantity}</p>
                <p>Rs. {item.item.price * item.quantity}</p>
              </div>
            </div>
          ))}
          <div className="total">SUBTOTAL: Rs. {subtotal}</div>
          <br />
          <input className="checkout-button" type="button" value="Checkout" />
        </div>
      )}
    </div>
  );
};

export default CartPage;
